if (P1.empty() || P2.empty()) return false;

const auto& v1 = P1.vertices();
const auto& v2 = P2.vertices();
const std::size_t n1 = v1.size();
const std::size_t n2 = v2.size();

auto onSegment = [](const Point2d& p, const Point2d& q, const Point2d& r) -> bool {
    if (q.x <= std::max(p.x, r.x) && q.x >= std::min(p.x, r.x) &&
        q.y <= std::max(p.y, r.y) && q.y >= std::min(p.y, r.y))
        return true;
    return false;
};

auto orientation = [](const Point2d& p, const Point2d& q, const Point2d& r) -> int {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (std::abs(val) < 1e-12) return 0;
    return (val > 0) ? 1 : 2;
};

auto segmentsIntersect = [&](const Point2d& p1, const Point2d& q1,
                             const Point2d& p2, const Point2d& q2) -> bool {
    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);

    if (o1 != o2 && o3 != o4) return true;

    if (o1 == 0 && onSegment(p1, p2, q1)) return true;
    if (o2 == 0 && onSegment(p1, q2, q1)) return true;
    if (o3 == 0 && onSegment(p2, p1, q2)) return true;
    if (o4 == 0 && onSegment(p2, q1, q2)) return true;

    return false;
};

auto pointInPolygon = [&](const Point2d& p, const std::vector<Point2d>& poly) -> bool {
    bool inside = false;
    for (std::size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        const Point2d& a = poly[i];
        const Point2d& b = poly[j];
        if (((a.y > p.y) != (b.y > p.y)) &&
            (p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x))
            inside = !inside;
    }
    return inside;
};

for (std::size_t i = 0; i < n1; ++i) {
    const Point2d& a1 = v1[i];
    const Point2d& b1 = v1[(i + 1) % n1];
    for (std::size_t j = 0; j < n2; ++j) {
        const Point2d& a2 = v2[j];
        const Point2d& b2 = v2[(j + 1) % n2];
        if (segmentsIntersect(a1, b1, a2, b2)) return true;
    }
}

for (const Point2d& p : v1) {
    if (pointInPolygon(p, v2)) return true;
}
for (const Point2d& p : v2) {
    if (pointInPolygon(p, v1)) return true;
}

return false;
// END_CODE

